import React from 'react';
import member from '../../../assets/member.png';
import President from '../../../assets/president.png';

const roles = [
  { title: 'President', name: 'Mr. XYZ Patel', img: President },
  { title: 'Vice-President', name: 'Mr. XYZ Patel', img: President },
  { title: 'Secretary', name: 'Mr. XYZ Patel', img: President },
  { title: 'Treasurer', name: 'Mr. XYZ Patel', img: member },
];

const members = Array(8).fill({
  title: 'Member',
  name: 'Mr. XYZabc Patel',
  img: member,
});

export default function CommitteeTree() {
  return (
    <section className="py-10 flex flex-col items-center">
      <h2 className="text-2xl font-bold mb-10">Our Committee</h2>

      {/* President */}
      <div className="relative flex flex-col items-center">
        <MemberCard {...roles[0]} />

        {/* Vertical line below president */}
        <div className="w-px bg-gray-400 h-8 mx-auto"></div>

        {/* Second Level: VP, Secretary, Treasurer */}
        <div className="flex justify-center space-x-12 relative">

          {/* Horizontal connector line */}
          <div className="absolute top-0 left-0 right-0 h-px bg-gray-400"></div>

          {/* Vertical connector lines from horizontal line to each card */}
          {roles.slice(1).map((role, i) => (
            <div key={i} className="flex flex-col items-center relative">
              {/* Vertical line */}
              <div className="w-px bg-gray-400 h-8 mb-2"></div>
              <MemberCard {...role} />
            </div>
          ))}
        </div>

        {/* Vertical line below second level */}
        <div className="w-px bg-gray-400 h-8 mx-auto mt-6"></div>

        {/* Members grid (3rd level) */}
        <div className="grid grid-cols-4 gap-8 mt-6">
          {members.map((member, i) => (
            <MemberCard key={i} {...member} />
          ))}
        </div>
      </div>
    </section>
  );
}

function MemberCard({ img, title, name }) {
  return (
    <div className="text-center p-4 border rounded shadow w-32 mx-auto bg-white">
      <img src={img} alt={title} className="w-16 h-16 mx-auto rounded-full mb-2" />
      <div className="font-semibold text-sm">{title}</div>
      <div className="text-xs text-gray-600">{name}</div>
    </div>
  );
}
